void add_seg(float x0, float y0, float z0, float x1, float y1, float z1, float thickness, __global float* out_pos, __global float* out_col, int* count, int max_vertices) {
    float dx = x1 - x0;
    float dy = y1 - y0;
    float dz = z1 - z0;
    float len = sqrt(dx*dx + dy*dy + dz*dz);
    if (len < 0.00001f) { return; }
    dx /= len;
    dy /= len;
    dz /= len;
    float upx = 1.0f;
    float upy = 0.0f;
    float upz = 0.0f;
    if (fabs(dx) > 0.9f) {
        upx = 0.0f;
        upy = 1.0f;
    }
    float ux = dy * upz - dz * upy;
    float uy = dz * upx - dx * upz;
    float uz = dx * upy - dy * upx;
    float ulen = sqrt(ux*ux + uy*uy + uz*uz);
    if (ulen < 0.00001f) { return; }
    ux /= ulen;
    uy /= ulen;
    uz /= ulen;
    float vx = dy * uz - dz * uy;
    float vy = dz * ux - dx * uz;
    float vz = dx * uy - dy * ux;
    float h = thickness * 0.5f;
    float su[4] = {-1.0f, 1.0f, 1.0f, -1.0f};
    float sv[4] = {-1.0f, -1.0f, 1.0f, 1.0f};
    float cx[8];
    float cy[8];
    float cz[8];
    for (int i = 0; i < 4; i++) {
        float ox = h * (su[i] * ux + sv[i] * vx);
        float oy = h * (su[i] * uy + sv[i] * vy);
        float oz = h * (su[i] * uz + sv[i] * vz);
        cx[i] = x0 + ox;
        cy[i] = y0 + oy;
        cz[i] = z0 + oz;
        cx[i + 4] = x1 + ox;
        cy[i + 4] = y1 + oy;
        cz[i + 4] = z1 + oz;
    }
    int tri[36] = {
        0, 2, 1, 0, 3, 2,
        4, 5, 6, 4, 6, 7,
        0, 1, 5, 0, 5, 4,
        1, 2, 6, 1, 6, 5,
        2, 3, 7, 2, 7, 6,
        3, 0, 4, 3, 4, 7
    };
    float r = 0.5f + dx * 0.5f;
    float g = 0.5f + dy * 0.5f;
    float b = 0.5f + dz * 0.5f;
    int start = *count;
    for (int i = 0; i < 36; i++) {
        int idx = start + i;
        if (idx < max_vertices) {
            int c = tri[i];
            out_pos[idx * 3 + 0] = cx[c];
            out_pos[idx * 3 + 1] = cy[c];
            out_pos[idx * 3 + 2] = cz[c];
            out_col[idx * 3 + 0] = r;
            out_col[idx * 3 + 1] = g;
            out_col[idx * 3 + 2] = b;
        }
    }
    *count = start + 36;
}

__kernel void process(__global const float* in_pos, __global const float* in_col, int in_count, __global float* out_pos, __global float* out_col, __global int* out_count, int max_vertices) {
    int id = get_global_id(0);
    if (id == 0) {
        float p0x = chf("Point 1 X", -0.75f);
        float p0y = chf("Point 1 Y", 0.05f);
        float p0z = chf("Point 1 Z", 0.0f);
        float p1x = chf("Point 2 X", -0.25f);
        float p1y = chf("Point 2 Y", 1.05f);
        float p1z = chf("Point 2 Z", 0.0f);
        float p2x = chf("Point 3 X", 0.25f);
        float p2y = chf("Point 3 Y", 0.05f);
        float p2z = chf("Point 3 Z", 0.0f);
        float p3x = chf("Point 4 X", 0.75f);
        float p3y = chf("Point 4 Y", 1.05f);
        float p3z = chf("Point 4 Z", 0.0f);
        int segments = chi("Segments", 24);
        if (segments < 1) { segments = 1; }
        if (segments > 256) { segments = 256; }
        float thickness = chf("Thickness", 0.02f);
        int count = 0;
        float prev_x = p0x;
        float prev_y = p0y;
        float prev_z = p0z;
        for (int i = 0; i < segments; i++) {
            float t = (float)(i + 1) / (float)segments;
            float s = 1.0f - t;
            float b0 = s * s * s;
            float b1 = 3.0f * s * s * t;
            float b2 = 3.0f * s * t * t;
            float b3 = t * t * t;
            float x = b0 * p0x + b1 * p1x + b2 * p2x + b3 * p3x;
            float y = b0 * p0y + b1 * p1y + b2 * p2y + b3 * p3y;
            float z = b0 * p0z + b1 * p1z + b2 * p2z + b3 * p3z;
            add_seg(prev_x, prev_y, prev_z, x, y, z, thickness, out_pos, out_col, &count, max_vertices);
            prev_x = x;
            prev_y = y;
            prev_z = z;
        }
        *out_count = count;
    }
}
